package io.github.deepseekbridge;
import android.app.Application;import android.content.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk={26,33},manifest=Config.NONE,application=Application.class)
public class NetworkSettingsTest {
 private Context context;
 @Before public void before(){context=RuntimeEnvironment.getApplication();context.getSharedPreferences("studio-network",0).edit().clear().commit();NetworkSettings.install(context);}
 @After public void after(){context.getSharedPreferences("studio-network",0).edit().clear().commit();}
 @Test(timeout=15000) public void proxyMustBeExplicitAndValidAndCanBeTurnedOff()throws Exception{assertEquals("system",NetworkSettings.config(context).getString("mode"));for(JSONObject value:new JSONObject[]{new JSONObject().put("mode","wrong"),new JSONObject().put("mode","http_proxy").put("host","https://subscription.example").put("port",7890),new JSONObject().put("mode","http_proxy").put("host","127.0.0.1").put("port",0)})try{NetworkSettings.configure(context,value);fail();}catch(IOException expected){}NetworkSettings.configure(context,new JSONObject().put("mode","http_proxy").put("host","127.0.0.1").put("port",12345));assertEquals(12345,NetworkSettings.config(context).getInt("port"));NetworkSettings.configure(context,new JSONObject().put("mode","system"));assertEquals("system",NetworkSettings.config(context).getString("mode"));}
 @Test(timeout=15000) public void httpProxyReceivesUnresolvedTargetAndHttpsUsesConnectWithoutLeakingBearer()throws Exception{
  try(ServerSocket proxy=new ServerSocket(0,1,InetAddress.getLoopbackAddress())){AtomicReference<String> captured=new AtomicReference<>();CountDownLatch done=new CountDownLatch(1);Thread server=new Thread(()->{try(Socket socket=proxy.accept()){socket.setSoTimeout(4000);BufferedReader reader=new BufferedReader(new InputStreamReader(socket.getInputStream(),StandardCharsets.ISO_8859_1));StringBuilder text=new StringBuilder();String line;while((line=reader.readLine())!=null&&!line.isEmpty())text.append(line).append('\n');captured.set(text.toString());socket.getOutputStream().write("HTTP/1.1 502 Fixture tunnel refusal\r\nContent-Length: 0\r\nConnection: close\r\n\r\n".getBytes(StandardCharsets.US_ASCII));}catch(Exception e){captured.set("failure: "+e);}finally{done.countDown();}});server.setDaemon(true);server.start();NetworkSettings.configure(context,new JSONObject().put("mode","http_proxy").put("host","127.0.0.1").put("port",proxy.getLocalPort()));HttpURLConnection c=NetworkSettings.open(new URL("https://unresolved-native-fixture.invalid/v1/models"));c.setConnectTimeout(4000);c.setReadTimeout(4000);c.setRequestProperty("Authorization","Bearer fixture-should-stay-inside-tls");try{c.getResponseCode();fail();}catch(IOException expected){}finally{c.disconnect();}assertTrue(done.await(5,TimeUnit.SECONDS));assertTrue(captured.get(),captured.get().startsWith("CONNECT unresolved-native-fixture.invalid:443"));assertFalse(captured.get(),captured.get().contains("fixture-should-stay-inside-tls"));}
 }
 @Test(timeout=15000) public void localApiBypassesExplicitProxy()throws Exception{
  NetworkSettings.configure(context,new JSONObject().put("mode","http_proxy").put("host","127.0.0.1").put("port",1));try(ServerSocket server=new ServerSocket(0,1,InetAddress.getLoopbackAddress())){Thread t=new Thread(()->{try(Socket s=server.accept()){s.setSoTimeout(2000);BufferedReader input=new BufferedReader(new InputStreamReader(s.getInputStream(),StandardCharsets.US_ASCII));String line;while((line=input.readLine())!=null&&!line.isEmpty()){}s.getOutputStream().write("HTTP/1.1 200 OK\r\nContent-Length: 2\r\nConnection: close\r\n\r\nok".getBytes(StandardCharsets.US_ASCII));}catch(IOException ignored){}});t.setDaemon(true);t.start();HttpURLConnection c=NetworkSettings.open(new URL("http://127.0.0.1:"+server.getLocalPort()+"/v1"));c.setConnectTimeout(2000);c.setReadTimeout(2000);assertEquals(200,c.getResponseCode());c.disconnect();}
 }
}
